import type { Call } from "./call.ts";

/**
 * The dynamic variables handed to the voice provider for one call: the call id and its
 * per-call token (see call-token.ts), so the agent's tool calls can authenticate. Both are
 * generated by the workflow and injected here; neither is ever produced by the provider's own
 * model — see AGENTS.md's rule that provider speech is data, never authority.
 */
export interface PlaceCallDynamicVariables {
  readonly call_id: string;
  readonly call_token: string;
}

export interface PlaceCallInput {
  readonly call: Call;
  readonly phoneE164: string;
  readonly dynamicVariables: PlaceCallDynamicVariables;
}

export interface PlaceCallResult {
  readonly externalId: string;
  /**
   * Twilio's CallSid for the phone leg, when the provider reports one: the only handle that can
   * hang the call up (ElevenLabs has no hang-up endpoint). `null` when there is none.
   */
  readonly callSid: string | null;
}

/**
 * Port for placing and cancelling one phone call with a voice provider. Implementations live
 * in `adapters/` (ElevenLabs Agents, Pipecat, or the in-process `simulated-voice.ts` used by
 * tests): the workflow depends on this interface only, so switching providers is a
 * configuration change, never a code change (see docs/architecture.md's voice tool contract).
 *
 * `placeCall` starts the call and resolves once the provider has accepted the request, with its
 * own conversation id (`externalId`); it never waits for the call to end — that arrives later
 * through the post-call webhook. `cancelCall` asks the provider to end an in-flight call by that
 * same `externalId`.
 */
export interface VoiceCallPort {
  placeCall(input: PlaceCallInput): Promise<PlaceCallResult>;
  cancelCall(externalId: string): Promise<void>;
}
